// goal: Generate i18n aggregation files
// eff: Collect locales from all plugins

import { OUTPUT_I18N_EN, OUTPUT_I18N_ZH } from './config.ts';
import { emitGeneratedFile, type GenerationMode } from './utils.ts';

/**
 * Generate i18n aggregation TypeScript files
 * @param {Array} allModules - All discovered modules
 */
export function generateI18n(allModules, mode: GenerationMode = 'write') {
	const header = `// AUTO-GENERATED - DO NOT EDIT
// Generated by: bun run generate-registry
// Source: {tools,scripts,system}/*/locales/{lang}.ts
`;

	const writeI18nFile = (lang, outputPath) => {
		const validModules = allModules.filter(m => lang === 'en' ? m.hasEn : m.hasZh);

		const imports = validModules.map(m => {
			const variable = m.id.replace(/-/g, '_');
			// Map dirType to folder
			const folder = m.dirType === 'system' ? 'system' : (m.dirType === 'scripts' ? 'scripts' : 'tools');
			return `import { ${lang} as ${variable} } from '../../${folder}/${m.dirName}/locales/${lang}';`;
		});

		const spread = validModules.map(m => {
			const variable = m.id.replace(/-/g, '_');
			return `\t...${variable},`;
		});

		const content = `${header}
${imports.join('\n')}

export const TOOLS_${lang.toUpperCase()} = {
${spread.join('\n')}
};
`;
		emitGeneratedFile(outputPath, content, mode, `i18n (${lang})`);
	};

	writeI18nFile('en', OUTPUT_I18N_EN);
	writeI18nFile('zh', OUTPUT_I18N_ZH);
}
